// 条例 第四条第(一)项; 实施办法 第七条: 寒暑假抵扣年休假, 多于年休假的不享受. 条例 第四条; 实施办法 第八条: 年度审核认定不享受的, 当年或下一年度无年休假.
// 条例 第五条; 实施办法 第九条: 跨年度安排只跨1个年度. 实施办法 第十条: 书面不休的天数不再计入.
const contract = ctx.subject.employment;
const started = get(contract, 'service_started_on', contract.effective_range.from);
const facts = get(contract, 'employee_extension_data.term_facts', {});
const reviews = get(facts, 'annual_leave_year_reviews', []);
const year = Number(ctx.as_of.slice(0, 4));
const review = (at) => first(reviews.filter((row) => row.year === at));
const band = ctx.lookup.service_bands.filter((row) => row.service_months <= calendar_completed_months(started, ctx.as_of)).at(-1);
const qualified = add_months(started, ctx.lookup.qualifying_service_months);
const share = Number(qualified.slice(0, 4)) === year ? (calendar_distance_days(qualified, year + '-12-31') + 1) / ctx.lookup.first_year_proration_days : 1;
const grant = band == null ? 0 : Math.floor(band.days * share);
const barred = get(review(year), 'disqualified', false) === true || get(review(year - 1), 'next_year_disqualified', false) === true;
const statutory = barred ? 0 : Math.max(0, grant - get(facts, 'school_vacation_days', 0));
const deferred = sum(reviews.filter((row) => row.year < year && row.year >= year - ctx.lookup.carry_forward_years).map((row) => row.deferred_days));
const spent = get(review(year), 'waived_days', 0) + get(review(year), 'deferred_days', 0);
return Math.max(0, statutory + deferred - spent);

